question.solution:
import heapq

def dijkstra_heap(edges, start):
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
        adj.setdefault(v, [])
    INF = float('inf')
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist.get(u, INF):
            continue
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, INF):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist

print(dijkstra_heap([('A', 'B', 1), ('A', 'C', 4), ('B', 'C', 2), ('B', 'D', 6), ('C', 'D', 3)], 'A'))
print(dijkstra_heap([('A', 'B', 2)], 'B'))
print(dijkstra_heap([('A', 'B', 1), ('B', 'C', 1), ('C', 'A', 1)], 'A'))
print(dijkstra_heap([('A', 'B', 5), ('A', 'B', 2)], 'A'))
print(dijkstra_heap([], 'A'))
